    "tfAddTopicBody": "ਫਲੈਸ਼ਕਾਰਡ ਟਾਪਿਕ ਨਾਲ ਜੁੜੇ ਹੁੰਦੇ ਹਨ। ਸਾਈਡਬਾਰ ਵਿੱਚ ਵਿਸ਼ਾ ਅਤੇ ਟਾਪਿਕ ਬਣਾਓ, ਫਿਰ ਕਾਰਡ ਲਿਖਣ ਲਈ ਵਾਪਸ ਆਓ।",
    "tfFirstTitle": "ਆਪਣੇ ਪਹਿਲੇ ਫਲੈਸ਼ਕਾਰਡ ਲਿਖੋ",
